"""R4 literal-output controls: RED-first core plus continuation controls.

Continued from the sealed r1 RED-first packet. D4 boundary migrations are
listed separately and are not applied to protected tests. These additive
controls do not substitute for the lead's full E2B suite.
"""

import json

from fi_instrumentation.instrumentation._image_cap import (
    _cap_base64_images_counted,
    cap_base64_images,
)

A = "__REDACTED__"
B = "[image-redacted]"
BS = chr(92)
P = "QUJD" * 40
H = "data:image/png;base64,"
HEAD = 'data:image/png;name="a' + BS + '" ' + "q" * 1200 + '"'
COMMA_HEAD = 'data:image/png;name="a' + BS + '" ,' + "q" * 1200 + '"'
HIDDEN_FLAG = ";ba" + BS + "u0073e64,"
TWO_LAYER = (BS + "u005cu0051UJD") * 40


def cap(value, maximum=64):
    return cap_base64_images(value, maximum, A)


# Expected outputs are literal form-B strings, not inferred from cap() or a
# second recognizer. The IDs retain the bound lens membership explicitly.
LENS_CASES = (
    ("R3-A-001-hidden-flag", HEAD + HIDDEN_FLAG + P, 64, "[image-redacted]"),
    ("R3-A-001-two-layer-payload", HEAD + ";base64," + TWO_LAYER, 64, "[image-redacted]"),
    ("BK-A-PY-001-quoted-comma-hidden-flag", COMMA_HEAD + HIDDEN_FLAG + P, 64, "[image-redacted]"),
    ("BK-A-PY-001-quoted-comma-two-layer-payload", COMMA_HEAD + ";base64," + TWO_LAYER, 64, "[image-redacted]"),
    ("BK-A-PY-002-decimal", HEAD + ";ba&#00000000115;e64," + P, 64, "[image-redacted]"),
    ("BK-A-PY-002-hex", HEAD + ";ba&#x0000000073;e64," + P, 64, "[image-redacted]"),
    ("BK-A-PY-003", HEAD + HIDDEN_FLAG + P, 1393, "[image-redacted]"),
    ("BK-B-001-numeric", HEAD + HIDDEN_FLAG + "&#x00000051;UJD" * 40, 64, "[image-redacted]"),
    ("BK-B-001-NewLine", HEAD + HIDDEN_FLAG + "&NewLine;" + P, 64, "[image-redacted]"),
    ("BK-B-002-surrogate-pair", HEAD + HIDDEN_FLAG + BS + "udb40" + BS + "udc00" + P, 64, "[image-redacted]"),
    ("BK-B-003", HEAD + HIDDEN_FLAG + P, 1393, "[image-redacted]"),
    ("decoder-parity-multi-character-reference", HEAD + HIDDEN_FLAG + "&fjlig;" * 80, 64, "[image-redacted]"),
    ("C2-transported-nonfinal-flag", "data:image/png;ba" + BS + 'u0073e64;name="a' + BS + '" ,' + "q" * 1200 + '",' + P, 64, "[image-redacted]"),
)


def test_r4_bound_lens_plain_literal_outputs():
    for case_id, value, maximum, expected in LENS_CASES:
        assert cap(value, maximum) == expected, case_id


def test_r4_bound_lens_independent_key_value_literal_outputs():
    for case_id, value, maximum, _ in LENS_CASES:
        key = "{" + json.dumps(value) + ':0,"keep":"ordinary words"}'
        member = '{"x":' + json.dumps(value) + ',"keep":"ordinary words"}'
        assert cap(key, maximum) == '{"[image-redacted]":0,"keep":"ordinary words"}', case_id
        assert cap(member, maximum) == '{"x":"[image-redacted]","keep":"ordinary words"}', case_id


def test_r4_budget_inheritance_literal_outputs():
    for value in (
        "%252522%25252541%252522",  # R3-A-003: fourth pass would decode %41.
        "%252522%252526%25252365%25253B%252522",  # BK-A-PY-004.
    ):
        assert cap(value) == "[image-redacted]"
        assert cap('{"x":' + json.dumps(value) + ',"keep":1}') == '{"x":"[image-redacted]","keep":1}'
    stable_at_three = "%252522%252541%252522"
    assert cap(stable_at_three) == stable_at_three


def test_r4_counted_whole_dominates_occurrence():
    # BK-B-004: one emitted B, not an A count plus a second output-backstop count.
    value = H + P + "!" + HEAD + HIDDEN_FLAG + P
    assert _cap_base64_images_counted(value, 64, A) == ("[image-redacted]", 1)
    doc = '{"x":' + json.dumps(value) + ',"other":' + json.dumps(H + P) + ',"keep":1}'
    assert _cap_base64_images_counted(doc, 64, A) == (
        '{"x":"[image-redacted]","other":"__REDACTED__","keep":1}', 2
    )


def test_r4_deep_strict_json_retains_syntax_and_sibling():
    # BK-B-005: iterative Q1 must not confuse a Python recursion limit with
    # invalid JSON. Deliberately do not call recursive json.loads on this doc.
    value = HEAD + HIDDEN_FLAG + P
    raw = "[" * 2000 + '{"keep":"ordinary words","x":' + json.dumps(value) + "}" + "]" * 2000
    expected = "[" * 2000 + '{"keep":"ordinary words","x":"[image-redacted]"}' + "]" * 2000
    assert _cap_base64_images_counted(raw, 64, A) == (expected, 1)


def test_r4_raw_a_quoted_pairs_and_optional_flag_whitespace():
    for header in (
        HEAD + ";base64,",
        COMMA_HEAD + ";base64,",
        "data:image/png; \tbase64 \t,",
        "data:image/png;base64;name=ordinary,",
    ):
        assert cap("left " + header + P + " right") == "left __REDACTED__ right"
    assert _cap_base64_images_counted(H + P, 64, A) == ("__REDACTED__", 1)


def test_r4_ignorable_transport_prefix_and_complete_continuation():
    # Includes the Khmer witnesses already present in the protected file;
    # these strengthen them to complete literal-output/count oracles.
    for code in (0x17B4, 0x17B5, 0x115F, 0x3164, 0xFFA0, 0x1D173, 0xE0000):
        char = chr(code)
        spellings = [char, "&#" + str(code) + ";"]
        if code <= 0xFFFF:
            spellings.append(BS + "u" + format(code, "04x"))
        else:
            high = 0xD800 + ((code - 0x10000) >> 10)
            low = 0xDC00 + ((code - 0x10000) & 0x3FF)
            spellings.append(BS + "u" + format(high, "04x") + BS + "u" + format(low, "04x"))
        spellings.append("".join("%" + format(byte, "02X") for byte in char.encode("utf-8")))
        for invisible in spellings:
            for raw in ("d" + invisible + "ata:image/png;base64," + P, H + P + invisible + P):
                assert cap(raw) == "[image-redacted]", (code, invisible)
                assert cap('{"x":' + json.dumps(raw) + ',"keep":1}') == '{"x":"[image-redacted]","keep":1}'
                assert cap("{" + json.dumps(raw) + ':0,"keep":1}') == '{"[image-redacted]":0,"keep":1}'


def test_r4_every_false_flag_benign_row_is_byte_identical():
    for header in (
        "data:image/png;base64=ordinary,",
        "data:image/png;base64suffix,",
        "data:image/png;name=base64,",
        'data:image/png;name="x;base64;y",',
        'data:image/png;name="x' + BS + '";base64;y",',
    ):
        raw = header + P
        for value, expected in (
            (raw, "[image-redacted]"),
            (json.dumps(raw), '"[image-redacted]"'),
            ('{"x":' + json.dumps(raw) + "}", '{"x":"[image-redacted]"}'),
        ):
            assert cap(value, 0) == expected


def test_r4_raw_and_transported_q1_split_rows_are_byte_identical():
    for raw in (
        '["data:image/png;name=", ";base64,QUJD"]',
        '{"data:image/png;name=":";base64,QUJD"}',
    ):
        # Only the enclosing syntax is transported; no new string concatenation
        # may be inferred while a complete strict document is revealed.
        for value in (
            raw,
            "%" + format(ord(raw[0]), "02X") + raw[1:-1] + "%" + format(ord(raw[-1]), "02X"),
            BS + "u" + format(ord(raw[0]), "04x") + raw[1:-1] + BS + "u" + format(ord(raw[-1]), "04x"),
            ("&lbrace;" if raw[0] == "{" else "&lbrack;") + raw[1:-1] + ("&rbrace;" if raw[-1] == "}" else "&rbrack;"),
        ):
            assert cap(value, 0) == value
        for depth in (7, 8, 9):
            value = raw
            for _ in range(depth):
                value = json.dumps(value)
            assert cap(value, 0) == value


def test_r4_nested_declared_payload_recursion_is_free():
    for depth in (7, 8, 9):
        raw = '{"data":"' + P + '","media_type":"image/png","keep":1}'
        expected = '{"data":"__REDACTED__","media_type":"image/png","keep":1}'
        for _ in range(depth):
            raw, expected = json.dumps(raw), json.dumps(expected)
        assert cap(raw) == expected


def test_r4_json_escaped_header_does_not_inflate_measure():
    url = 'data:image/png;name="sample";base64,' + P
    for depth in (1, 2, 4, 9):
        raw = "[" + url + "]"
        expected = "[__REDACTED__]"
        for _ in range(depth):
            raw, expected = json.dumps(raw), json.dumps(expected)
        assert cap(raw, len(url)) == raw
        assert cap(raw, len(url) + 1) == raw
        assert cap(raw, len(url) - 1) == expected


def test_r4_d4_boundary_is_explicit():
    assert cap("z" * 1_048_576) == "z" * 1_048_576
    assert cap("z" * 1_048_577) == "[image-redacted]"


def test_r4_transported_document_children_inherit_budget():
    raw = '%25257B%252522x%252522:%252522%25252541%252522%25257D'
    assert cap(raw) == '%25257B%252522x%252522:%252522[image-redacted]%252522%25257D'


def test_r4_structural_document_bound_is_fail_closed():
    # 17 logical document decompositions exceed the specified bound of 16.
    # Escaping one initial quote doubles output size at each level; this stays
    # below D4, so the structural bound (not the size bound) is exercised.
    value = '"x"'
    expected = '"[image-redacted]"'
    for _ in range(16):
        value = json.dumps(value)
    for _ in range(15):
        expected = json.dumps(expected)
    assert len(value) <= 1_048_576
    assert cap(value) == expected


def test_r4_stacktrace_is_a_distinct_unfenced_scope():
    url = 'data:image/png;name="sample";base64,' + P
    value = json.dumps(url)
    assert cap(value, len(url)) == value
    assert cap("ValueError: " + value + "\n", len(url)) == 'ValueError: "__REDACTED__"\n'
    hidden = json.dumps(BS + "u0064ata:image/png;base64," + P)
    assert cap("ValueError: " + hidden + "\n") == "[image-redacted]"


def test_r4_nested_nonconvergence_preserves_sibling_edits():
    delayed = BS + "u005c" * 128 + "u0064ata:image/png;base64," + P
    inner = json.dumps({"first": delayed, "pending": H + P, "last": H + P})
    raw = json.dumps({"opaque": inner, "ordinary": "retain", "shallow": H + P})
    expected_inner = '{"first": "[image-redacted]", "pending": "__REDACTED__", "last": "__REDACTED__"}'
    expected = json.dumps({"opaque": expected_inner, "ordinary": "retain", "shallow": "__REDACTED__"})
    assert _cap_base64_images_counted(raw, 64, A) == (expected, 4)


def test_r4_non_image_and_ordinary_controls_are_byte_identical():
    for raw in (
        "ordinary words",
        "see https://example.com/a,b?c=1",
        "data:audio/wav;base64," + P,
        "data:image/svg+xml,%3Csvg%3E",
        "data:image/png;base64,QUJD",
        "emoji \U0001F468‍\U0001F469 family",
    ):
        assert cap(raw) == raw


# R4C3: exact-raw runs must resume after an atom, not after a regex match
# that began inside that atom. These literal A oracles are RED on r4c2.
def test_r4c3_preview_unquoted_raw_gap_escapes():
    raw = "[" + (H + P).replace("Q", BS + "u0051") + "]"
    for maximum in (0, 1, 64):
        assert cap(raw, maximum) == ("[image-redacted]" if maximum == 0 else "[__REDACTED__]")


def test_r4c3_preview_percent_payload_tail():
    assert cap("left " + H + P + "%2FQUJD right") == "left __REDACTED__ right"


def test_r4c3_preview_malformed_mime_payload_atoms():
    for body in (P.replace("Q", BS + "u0051"), "QUJD" + BS + "r" + BS + "n" + P):
        raw = 'prefix data:image/png;name="a" b";base64,' + body + " suffix"
        assert cap(raw) == ("[image-redacted]" if body.startswith("QUJD" + BS + "r") else "prefix __REDACTED__ suffix")


def test_r4c3_raw_atom_suffix_threshold_and_q1_scope():
    for body in (
        (BS + "u0051UJD") * 40,
        P + "%2FQUJD",
        "QUJD" + BS + "r" + BS + "n" + P,
        ("&#81;UJD") * 40,
        ("&#000000000081;UJD") * 40,
        ("&#x000000000051;UJD") * 40,
        ("&fjlig;QUJD") * 40,
        ("&sol;QUJD") * 40,
        (BS + "/QUJD") * 40,
    ):
        url = H + body
        raw = "left " + url + " right"
        crlf = body == "QUJD" + BS + "r" + BS + "n" + P
        assert cap(raw, len(url)) == "[image-redacted]"
        assert cap(raw, len(url) + 1) == (raw if crlf else "[image-redacted]")
        assert cap(raw, len(url) - 1) == ("[image-redacted]" if crlf else "left __REDACTED__ right")
        document = '{"x":' + json.dumps(raw) + ',"keep":1}'
        assert cap(document, len(url)) == '{"x":"[image-redacted]","keep":1}'
        assert cap(document, len(url) - 1) == ('{"x":"[image-redacted]","keep":1}' if crlf else '{"x":"left __REDACTED__ right","keep":1}')
        key = "{" + json.dumps(raw) + ':0,"keep":1}'
        assert cap(key, len(url)) == '{"[image-redacted]":0,"keep":1}'
        assert cap(key, len(url) - 1) == ('{"[image-redacted]":0,"keep":1}' if crlf else '{"left __REDACTED__ right":0,"keep":1}')


def test_r4c3_exact_atom_ranges_union_once_and_keep_framing():
    url = H + (BS + "u0051UJD") * 40
    assert _cap_base64_images_counted(url, 64, A) == ("__REDACTED__", 1)
    # C1 is quote-agnostic: within its 1024-unit window the first prefix also
    # reaches the second flag, so overlapping raw ranges union to one edit.
    assert _cap_base64_images_counted("[" + url + "] [" + url + "]", 64, A) == (
        "[__REDACTED__]", 1
    )
    assert _cap_base64_images_counted(json.dumps([url, url]), 64, A) == (
        '["__REDACTED__", "__REDACTED__"]', 2
    )
    assert cap("ValueError: [" + url + "]\n") == "ValueError: [__REDACTED__]\n"
    assert cap("left " + url + BS + "r" + BS + "n right") == "left __REDACTED__\\r\\n right"
    assert cap("left " + url + "%GGQUJD right") == "left __REDACTED__%GGQUJD right"


def test_r4c3_decoded_only_run_still_uses_whole_fallback():
    assert cap("left " + H + TWO_LAYER + " right") == "[image-redacted]"
    assert cap("left " + H + P + chr(0x17B4) + P + " right") == "[image-redacted]"
    hidden_prefix = BS + "u0064ata:image/png;base64," + P
    assert cap("left " + hidden_prefix + " right") == "[image-redacted]"


# R4C5 additive controls; all preceding R4/R4C3 bytes are retained.
WS_SEPARATORS = (
    ("space", " "), ("tab", "\t"), ("ff", "\f"),
    ("space-lf", " \n"), ("crlf-space", "\r\n "),
    ("percent-space", "%20"), ("percent-tab", "%09"),
    ("percent-ff", "%0C"), ("percent-lf", "%0A"),
    ("decimal-space", "&#32;"), ("hex-tab", "&#x9;"),
    ("named-lf", "&NewLine;"), ("json-space", BS + "u0020"),
    ("json-tab", BS + "t"), ("json-ff", BS + "f"),
    ("percent-layer2", "%2520"), ("percent-layer3", "%252520"),
)
TD_SEPARATORS = (
    ("percent_comma", ";base64%2C"),
    ("json_comma", ";base64" + BS + "u002c"),
    ("named_comma", ";base64&comma;"),
    ("decimal_comma", ";base64&#44;"),
    ("hex_comma", ";base64&#x2c;"),
    ("zero_comma", ";base64&#0000000044;"),
    ("percent_semicolon", "%3Bbase64,"),
    ("json_semicolon", BS + "u003bbase64,"),
    ("named_semicolon", "&semi;base64,"),
    ("decimal_semicolon", "&#59;base64,"),
    ("hex_semicolon", "&#x3b;base64,"),
    ("zero_semicolon", "&#x000000003b;base64,"),
    ("percent_both", "%3Bbase64%2C"),
    ("layer2_both", "%253Bbase64%252C"),
    ("layer3_both", "%25253Bbase64%25252C"),
    ("nonfinal_flag", "%3Bbase64;name=z,"),
    ("earlier_parameter", "%3Bx=y;base64,"),
)


def test_r4c5_ws_small_chunks_and_q1_literal_outputs():
    for label, separator in WS_SEPARATORS:
        value = H + separator.join(["QUJD"] * 40)
        assert cap(value) == "[image-redacted]", label
        assert cap('{' + json.dumps(value) + ':0,"keep":1}') == '{"[image-redacted]":0,"keep":1}', label
        assert cap('{"m":' + json.dumps("x " + value + " y") + ',"keep":1}') == '{"m":"[image-redacted]","keep":1}', label


def test_r4c5_ws_mixed_transport_ignorable_chain():
    separators = (" ", "\t", chr(0x17B4), BS + "u0020")
    value = H + "QUJD" + "".join(separators[i % 4] + "QUJD" for i in range(39))
    assert cap(value) == "[image-redacted]"
    assert cap('{"m":' + json.dumps(value) + ',"keep":"ordinary"}') == '{"m":"[image-redacted]","keep":"ordinary"}'


def test_r4c5_ws_first_large_remainder_and_caption():
    assert cap(H + P + " " + P) == "[image-redacted]"
    assert cap(H + P + " " + " ".join(["QUJD"] * 17)) == "[image-redacted]"
    tail = " ".join(["QUJD"] * 16)
    assert cap(H + P + " " + tail) == "__REDACTED__ " + tail
    assert cap("diagnostic " + H + P + " caption retained", len(H + P) - 1) == "diagnostic __REDACTED__ caption retained"
    assert _cap_base64_images_counted(H + P + " " + P, 64, A) == ("[image-redacted]", 1)


def test_r4c5_ws_threshold_and_non_ascii_boundaries():
    value = H + " ".join(["QUJD"] * 10)
    assert cap(value, len(H) + 40) == value
    assert cap(value, len(H) + 41) == value
    assert cap(value, len(H) + 39) == "[image-redacted]"
    short = H + "QUJD" + " " * 100 + "QUJD"
    assert cap(short) == short
    for separator in (chr(11), chr(0xA0), "!", "."):
        value = H + separator.join(["QUJD"] * 40)
        assert cap(value) == value
    assert cap(H + "\r\n".join(["QUJD"] * 40)) == "[image-redacted]"


def test_r4c5_td_long_short_and_q1_literal_outputs():
    for label, separator in TD_SEPARATORS:
        for length in (1, 1024):
            value = "data:image/png;name=" + "q" * length + separator + P
            assert cap(value) == "[image-redacted]", (label, length)
            assert cap("{" + json.dumps(value) + ':0,"keep":1}') == '{"[image-redacted]":0,"keep":1}', (label, length)
            assert cap('{"x":' + json.dumps(value) + ',"keep":1}') == '{"x":"[image-redacted]","keep":1}', (label, length)


def test_r4c5_td_raw_pairs_at_cap_and_whitespace_composition():
    for length in (1, 1024):
        value = "data:image/png;name=" + "q" * length + ";base64," + P
        assert cap(value) == "__REDACTED__"
        assert cap("{" + json.dumps(value) + ':0,"keep":1}') == '{"__REDACTED__":0,"keep":1}'
        assert cap('{"x":' + json.dumps(value) + ',"keep":1}') == '{"x":"__REDACTED__","keep":1}'
    for label, separator in TD_SEPARATORS:
        value = "data:image/png;name=q" + separator + "QUJD"
        assert cap(value, len(value)) == value, label
        assert cap(value, len(value) - 1) == "[image-redacted]", label
    value = "data:image/png;name=" + "q" * 1024 + "%3Bbase64%2C" + " ".join(["QUJD"] * 40)
    assert cap(value) == "[image-redacted]"


def test_r4c5_td_retains_raw_quote_ownership_and_false_flags():
    stem = "data:image/png;name=" + "q" * 1024
    for flag in ("base64=ordinary", "base64suffix", "name=base64"):
        value = stem + "%3B" + flag + "%2C" + P
        assert cap(value) == value
    value = stem + '%3Bnote="x' + BS + '";base64;z",' + P
    assert cap(value) == value
    genuine = stem + ';note="x' + BS + '";z"%3Bbase64%2C' + P
    assert cap(genuine) == "[image-redacted]"
    split = '["data:image/png;name=", "%3Bbase64%2C' + P + '"]'
    assert cap(split) == split


def test_r4c5_td_and_ws_do_not_cross_q1_siblings():
    value = H + " ".join(["QUJD"] * 40)
    raw = '{"bad":' + json.dumps(value) + ',"normal":' + json.dumps(H + P) + ',"tail":"QUJD QUJD","keep":1}'
    assert _cap_base64_images_counted(raw, 64, A) == ('{"bad":"[image-redacted]","normal":"__REDACTED__","tail":"QUJD QUJD","keep":1}', 2)


def test_r4c5_ws_d2_atom_remainders_and_reference_union():
    for remainder in ("%51" * 30, (BS + "u0051") * 11, "&fjlig;" * 10):
        assert cap(H + P + " " + remainder) == "[image-redacted]"
    remainder = "&fjlig;" * 9
    assert cap(H + P + " " + remainder) == "__REDACTED__ " + remainder
    value = H + "%51" * 10 + " " + "%51" * 10
    assert cap(value, len(H) + 60) == value
    assert cap(value, len(H) + 59) == "[image-redacted]"
    assert cap(value, len(H) + 61) == value


# R4C6 adds only equivalence controls; all preceding test bytes are retained.
def test_r4c6_many_header_literal_outputs_and_counts():
    for copies in (0, 1, 2, 45, 46, 47, 48, 49, 50, 70):
        value = H * copies
        expected = A + H[4:] if copies >= 47 else value
        count = int(copies >= 47)
        assert _cap_base64_images_counted(value, 1000, A) == (expected, count)
        document = '{"x":' + json.dumps(value) + ',"keep":"ordinary"}'
        expected_document = '{"x":' + json.dumps(expected) + ',"keep":"ordinary"}'
        assert _cap_base64_images_counted(document, 1000, A) == (expected_document, count)
    empty_runs = (H + "!") * 70
    assert _cap_base64_images_counted(empty_runs, 0, A) == ("[image-redacted]", 1)


def test_r4c6_occurrence_optimization_matches_frozen_r4c5():
    # Freeze only the changed function. All other functions must remain the
    # r4c5 bytes, so running the public counted API through this reference
    # covers Q1, work exhaustion and whole-scope dominance as well as ranges.
    from fi_instrumentation.instrumentation import _image_cap as impl

    def reference(view, maximum, raw, work, mime, source=""):
        text = view.text
        prefixes = impl._prefixes(text, work)
        if not prefixes:
            return []
        runs = impl._run_ends(text, raw, work)
        chains = impl._chain_counts(view, work)
        transported = impl._mime_ends(text, work, transport=view, source=source) if not raw else None
        flags = [(m.start(), m.end()) for m in impl._FLAG.finditer(text)]
        inverse = None
        if view.ends is not None:
            inverse = {end: i + 1 for i, end in enumerate(view.ends)}
        result = []
        low = high = 0
        for start, prefix_end in prefixes:
            while low < len(flags) and flags[low][0] < prefix_end:
                low += 1
            high = max(high, low)
            while high < len(flags) and flags[high][0] <= start + impl._BACKSTOP_HEADER_WINDOW:
                high += 1
            headers = {(end, False) for _, end in flags[low:high]}
            raw_header = mime[view.end(prefix_end - 1)]
            header = inverse.get(raw_header, 0) if inverse is not None else raw_header
            if header:
                headers.add((header, False))
            if transported is not None and transported[prefix_end]:
                headers.add((transported[prefix_end], True))
            for header_end, transported_header in headers:
                work.spend(1)
                end = runs[header_end]
                counting = (end > header_end and
                            max(end - start, view.end(end - 1) - view.start(start)) > maximum)
                whole = counting and transported_header
                if chains is not None:
                    if counting:
                        whole = whole or max(chains[0][end], chains[1][end]) > maximum
                    elif chains[0][header_end]:
                        header_length = max(header_end - start,
                                            view.end(header_end - 1) - view.start(start))
                        whole = header_length + max(chains[0][header_end], chains[1][header_end]) > maximum
                if whole:
                    return [(start, header_end, max(end, header_end), True)]
                if counting:
                    result.append((start, header_end, end, False))
        return result

    pieces = (
        H, H + "!", H + "QUJD", H + P,
        H + "QUJD QUJD", H + P + " " + P,
        "data:image/png;base64;name=z," + P,
        "data:image/png;name=q%3Bbase64%2C" + P,
        'data:image/png;name="x' + BS + '\";base64;y",' + P,
        H + "%51" * 10 + " " + "%51" * 10,
        H + "&fjlig;" * 10, H + P + chr(0x17B4) + P,
    )
    values = [H * n for n in (1, 2, 48, 49, 50, 70)]
    values.extend(pieces)
    values.extend(H * 50 + "!" + piece for piece in pieces)
    values.extend(piece + "!" + H * 50 for piece in pieces)
    values.extend(pieces[i] + "!" + pieces[(i + 5) % len(pieces)] for i in range(len(pieces)))
    optimized = impl._occurrences
    try:
        for index, value in enumerate(values):
            for maximum in (0, 24, 64, 1000, len(value)):
                for scoped in (value, '{"x":' + json.dumps(value) + ',"keep":"ordinary"}'):
                    impl._occurrences = reference
                    expected = impl._cap_base64_images_counted(scoped, maximum, A)
                    impl._occurrences = optimized
                    assert impl._cap_base64_images_counted(scoped, maximum, A) == expected, (index, maximum)
    finally:
        impl._occurrences = optimized


# R4C7: append-only literal parity and quoted-header R-FIX witnesses.


def test_r4c7_ref_literal():
    cases = (
        ('ref_literal/R4C5-TS-REDACTION-COMPLETENESS-001', 'data:image/png;ba&#115;e64;name=x,QUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJDQUJD', 64, '[image-redacted]', 1),
    )
    for case_id, value, maximum, expected, count in cases:
        assert _cap_base64_images_counted(value, maximum, A) == (expected, count), case_id
        assert cap(value, maximum) == expected, case_id
        assert _cap_base64_images_counted(expected, maximum, A) == (expected, 0), case_id


